package com.androidhit.lumadrift.data;

import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/** Original Prism chapter fiction. It introduces no gameplay object, reward or deadline. */
public final class PrismStoryStrings {
    private static final Map<String, String[]> TEXT = new LinkedHashMap<>();
    static {
        add("prism_title_1", "A borrowed spark", "Une étincelle prêtée", "Ein geliehener Funke", "Una chispa prestada", "Uma faísca emprestada", "Una scintilla in prestito");
        add("prism_intro_1", "Nova finds a quiet Prism in First Light. Its empty facets catch a tiny glow.", "Nova découvre un Prisme silencieux à Première lueur. Une petite lumière glisse sur ses facettes vides.", "Nova findet im Ersten Licht ein stilles Prisma. Ein kleiner Schimmer liegt auf seinen leeren Facetten.", "Nova encuentra un Prisma silencioso en Primera luz. Un pequeño brillo recorre sus facetas vacías.", "Nova encontra um Prisma silencioso na Primeira luz. Um pequeno brilho percorre as facetas vazias.", "Nova trova un Prisma silenzioso a Prima luce. Un piccolo bagliore sfiora le sue facce vuote.");
        add("prism_objective_1", "Explore First Light and collect its ten Guardian fragments.", "Explore Première lueur et récupère les dix fragments de ses gardiens.", "Erkunde Erstes Licht und sammle die zehn Wächterfragmente.", "Explora Primera luz y recoge sus diez fragmentos de guardianes.", "Explora a Primeira luz e recolhe os dez fragmentos dos seus guardiões.", "Esplora Prima luce e raccogli i dieci frammenti dei suoi guardiani.");
        add("prism_after_1", "The first facet glows. Nova can see a path through the mint grass.", "La première facette s’illumine. Nova aperçoit un chemin dans l’herbe menthe.", "Die erste Facette leuchtet. Nova erkennt einen Weg durch das Minzgras.", "La primera faceta se ilumina. Nova ve un camino entre la hierba de menta.", "A primeira faceta brilha. Nova vê um caminho pela erva menta.", "La prima faccia si illumina. Nova vede un sentiero nell’erba alla menta.");
        add("prism_title_2", "The meadow’s lost note", "La note égarée des prairies", "Der verlorene Wiesenton", "La nota perdida del prado", "A nota perdida dos prados", "La nota perduta del prato");
        add("prism_intro_2", "A soft note wanders through Mint Meadows. Nova follows it between the swaying leaves.", "Une note légère traverse les Prairies menthe. Nova la suit entre les feuilles qui dansent.", "Ein leiser Ton zieht durch die Minzwiesen. Nova folgt ihm zwischen wogenden Blättern.", "Una nota suave cruza los Prados menta. Nova la sigue entre las hojas que se mecen.", "Uma nota suave atravessa os Prados menta. Nova segue-a entre as folhas que dançam.", "Una nota lieve attraversa i Prati menta. Nova la segue tra le foglie che ondeggiano.");
        add("prism_objective_2", "Follow Mint Meadows and collect its ten Guardian fragments.", "Parcours les Prairies menthe et récupère les dix fragments de leurs gardiens.", "Folge den Minzwiesen und sammle die zehn Wächterfragmente.", "Recorre los Prados menta y recoge sus diez fragmentos de guardianes.", "Percorre os Prados menta e recolhe os dez fragmentos dos seus guardiões.", "Percorri i Prati menta e raccogli i dieci frammenti dei loro guardiani.");
        add("prism_after_2", "The meadow’s note settles into the Prism. Its glow now has a gentle rhythm.", "La note des prairies trouve sa place dans le Prisme. Sa lumière suit un rythme tout doux.", "Der Wiesenton findet ins Prisma. Sein Licht hat nun einen sanften Rhythmus.", "La nota del prado encuentra su sitio en el Prisma. Su luz tiene un ritmo suave.", "A nota dos prados encontra lugar no Prisma. A sua luz ganha um ritmo suave.", "La nota del prato trova posto nel Prisma. La sua luce ha un ritmo gentile.");
        add("prism_title_3", "A circle on the tide", "Un cercle sur la marée", "Ein Kreis auf der Flut", "Un círculo en la marea", "Um círculo na maré", "Un cerchio sulla marea");
        add("prism_intro_3", "At Peach Coast, each wave breaks the Prism’s reflection into little pieces. Nova watches them return.", "Sur la Côte pêche, chaque vague disperse le reflet du Prisme. Nova regarde les éclats revenir.", "An der Pfirsichküste zerlegt jede Welle das Spiegelbild des Prismas. Nova sieht die Splitter wiederkehren.", "En Costa melocotón, cada ola divide el reflejo del Prisma. Nova observa cómo vuelve a unirse.", "Na Costa pêssego, cada onda divide o reflexo do Prisma. Nova observa os pedaços a regressar.", "Sulla Costa pesca, ogni onda divide il riflesso del Prisma. Nova guarda i frammenti tornare.");
        add("prism_objective_3", "Trace Peach Coast and collect its ten Guardian fragments.", "Longe la Côte pêche et récupère les dix fragments de ses gardiens.", "Erkunde die Pfirsichküste und sammle die zehn Wächterfragmente.", "Recorre Costa melocotón y recoge sus diez fragmentos de guardianes.", "Percorre a Costa pêssego e recolhe os dez fragmentos dos seus guardiões.", "Percorri la Costa pesca e raccogli i dieci frammenti dei suoi guardiani.");
        add("prism_after_3", "A warm circle holds in the water. The Prism carries the coast’s soft colour.", "Un cercle chaud se dessine sur l’eau. Le Prisme garde la couleur douce de la côte.", "Ein warmer Kreis bleibt auf dem Wasser. Das Prisma trägt die sanfte Farbe der Küste.", "Un círculo cálido se dibuja en el agua. El Prisma guarda el suave color de la costa.", "Um círculo quente desenha-se na água. O Prisma guarda a cor suave da costa.", "Un cerchio caldo resta sull’acqua. Il Prisma custodisce il colore tenue della costa.");
        add("prism_title_4", "Threads between clouds", "Des fils entre les nuages", "Fäden zwischen Wolken", "Hilos entre las nubes", "Fios entre as nuvens", "Fili tra le nuvole");
        add("prism_intro_4", "Cloud Gardens seem far apart until sunlight draws fine threads between them. Nova looks for the meeting points.", "Les Jardins nuage semblent séparés. Puis le soleil trace des fils entre eux. Nova cherche où ils se rejoignent.", "Die Wolkengärten wirken getrennt. Sonnenlicht zieht feine Fäden dazwischen. Nova sucht ihre Treffpunkte.", "Los Jardines nube parecen separados. La luz dibuja hilos entre ellos. Nova busca dónde se unen.", "Os Jardins nuvem parecem separados. A luz traça fios entre eles. Nova procura onde se encontram.", "I Giardini nuvola sembrano separati. La luce disegna fili tra loro. Nova cerca i punti d’incontro.");
        add("prism_objective_4", "Visit Cloud Gardens and collect their ten Guardian fragments.", "Traverse les Jardins nuage et récupère les dix fragments de leurs gardiens.", "Besuche die Wolkengärten und sammle die zehn Wächterfragmente.", "Visita los Jardines nube y recoge sus diez fragmentos de guardianes.", "Visita os Jardins nuvem e recolhe os dez fragmentos dos seus guardiões.", "Visita i Giardini nuvola e raccogli i dieci frammenti dei loro guardiani.");
        add("prism_after_4", "The threads form a small sky map inside the Prism. No garden looks quite so far away.", "Les fils dessinent une carte du ciel dans le Prisme. Les jardins semblent plus proches.", "Die Fäden bilden eine kleine Himmelskarte im Prisma. Die Gärten scheinen nun näher.", "Los hilos forman un pequeño mapa del cielo en el Prisma. Los jardines parecen más cercanos.", "Os fios formam um pequeno mapa do céu no Prisma. Os jardins parecem mais próximos.", "I fili formano una piccola mappa del cielo nel Prisma. I giardini sembrano più vicini.");
        add("prism_title_5", "The lagoon’s clear shape", "La forme claire du lagon", "Die klare Form der Lagune", "La forma clara de la laguna", "A forma clara da lagoa", "La forma limpida della laguna");
        add("prism_intro_5", "Crystal Lagoon shows many reflections at once. Nova waits for the ripples to reveal one clear shape.", "Le Lagon cristal mêle les reflets. Nova observe les rides de l’eau jusqu’à distinguer une forme claire.", "Die Kristalllagune zeigt viele Spiegelbilder. Nova wartet, bis die Wellen eine klare Form zeigen.", "La Laguna cristal mezcla muchos reflejos. Nova observa las ondas hasta distinguir una forma clara.", "A Lagoa cristal mistura os reflexos. Nova observa as ondas até distinguir uma forma clara.", "La Laguna cristallo mescola i riflessi. Nova osserva le onde finché appare una forma limpida.");
        add("prism_objective_5", "Explore Crystal Lagoon and collect its ten Guardian fragments.", "Explore le Lagon cristal et récupère les dix fragments de ses gardiens.", "Erkunde die Kristalllagune und sammle die zehn Wächterfragmente.", "Explora la Laguna cristal y recoge sus diez fragmentos de guardianes.", "Explora a Lagoa cristal e recolhe os dez fragmentos dos seus guardiões.", "Esplora la Laguna cristallo e raccogli i dieci frammenti dei suoi guardiani.");
        add("prism_after_5", "The lagoon facet is clear. Each reflection keeps its own place in the light.", "La facette du lagon devient limpide. Chaque reflet trouve sa place dans la lumière.", "Die Lagunenfacette ist klar. Jedes Spiegelbild hat seinen Platz im Licht.", "La faceta de la laguna queda clara. Cada reflejo encuentra su lugar en la luz.", "A faceta da lagoa fica límpida. Cada reflexo encontra o seu lugar na luz.", "La faccia della laguna è limpida. Ogni riflesso trova il suo posto nella luce.");
        add("prism_title_6", "A canopy of small stars", "Une voûte de petites étoiles", "Ein Dach aus kleinen Sternen", "Un dosel de pequeñas estrellas", "Uma copa de pequenas estrelas", "Una volta di piccole stelle");
        add("prism_intro_6", "The Star Orchard rests under a dim canopy. Nova notices tiny lights waiting between the branches.", "Le Verger étoilé repose sous une voûte pâle. Nova remarque de petites lumières entre les branches.", "Der Sternenobstgarten ruht im Dämmerlicht. Nova entdeckt kleine Lichter zwischen den Ästen.", "El Huerto estelar descansa bajo un dosel tenue. Nova descubre luces entre las ramas.", "O Pomar estelar repousa sob uma copa ténue. Nova descobre pequenas luzes entre os ramos.", "Il Frutteto stellare riposa sotto una volta tenue. Nova scorge piccole luci tra i rami.");
        add("prism_objective_6", "Cross the Star Orchard and collect its ten Guardian fragments.", "Traverse le Verger étoilé et récupère les dix fragments de ses gardiens.", "Durchquere den Sternenobstgarten und sammle die zehn Wächterfragmente.", "Cruza el Huerto estelar y recoge sus diez fragmentos de guardianes.", "Atravessa o Pomar estelar e recolhe os dez fragmentos dos seus guardiões.", "Attraversa il Frutteto stellare e raccogli i dieci frammenti dei suoi guardiani.");
        add("prism_after_6", "Small stars gather above the orchard. Their pattern becomes a new facet of the Prism.", "De petites étoiles se rassemblent au-dessus du verger. Leur dessin devient une facette du Prisme.", "Kleine Sterne sammeln sich über dem Obstgarten. Ihr Muster wird zu einer neuen Prismafacette.", "Pequeñas estrellas se reúnen sobre el huerto. Su dibujo forma una nueva faceta del Prisma.", "Pequenas estrelas juntam-se sobre o pomar. O seu desenho forma uma nova faceta do Prisma.", "Piccole stelle si raccolgono sul frutteto. Il loro disegno diventa una nuova faccia del Prisma.");
        add("prism_title_7", "A place at the moon table", "Une place à la table lunaire", "Ein Platz am Mondtisch", "Un lugar en la mesa lunar", "Um lugar à mesa lunar", "Un posto alla tavola lunare");
        add("prism_intro_7", "The Moon Festival has a quiet table for every companion. Nova brings a little light to its centre.", "La Fête lunaire garde une place pour chaque compagnon. Nova apporte une petite lumière au centre de la table.", "Beim Mondfest gibt es einen Platz für jeden Gefährten. Nova bringt ein kleines Licht in die Tischmitte.", "El Festival lunar guarda un sitio para cada compañero. Nova lleva una luz al centro de la mesa.", "O Festival lunar guarda um lugar para cada companheiro. Nova leva uma luz ao centro da mesa.", "La Festa lunare tiene un posto per ogni compagno. Nova porta una luce al centro della tavola.");
        add("prism_objective_7", "Visit the Moon Festival and collect its ten Guardian fragments.", "Visite la Fête lunaire et récupère les dix fragments de ses gardiens.", "Besuche das Mondfest und sammle die zehn Wächterfragmente.", "Visita el Festival lunar y recoge sus diez fragmentos de guardianes.", "Visita o Festival lunar e recolhe os dez fragmentos dos seus guardiões.", "Visita la Festa lunare e raccogli i dieci frammenti dei suoi guardiani.");
        add("prism_after_7", "The table glows softly. This facet keeps a place for a companion, even after a long pause.", "La table s’éclaire doucement. Cette facette garde une place pour un compagnon, même après une longue pause.", "Der Tisch leuchtet sanft. Diese Facette hält einen Platz frei, auch nach einer langen Pause.", "La mesa brilla suavemente. Esta faceta guarda un sitio para un compañero, incluso tras una larga pausa.", "A mesa brilha suavemente. Esta faceta guarda lugar para um companheiro, mesmo depois de uma longa pausa.", "La tavola si illumina piano. Questa faccia tiene un posto per un compagno, anche dopo una lunga pausa.");
        add("prism_title_8", "Warm lanterns in the grove", "Des lanternes douces dans le bois", "Warme Laternen im Hain", "Faroles cálidos en el bosque", "Lanternas quentes no bosque", "Lanterne calde nel bosco");
        add("prism_intro_8", "In Pumpkin Grove, little lanterns cast enormous shadows. Nova follows their warm glow, not their size.", "Dans le Bois citrouille, de petites lanternes font de grandes ombres. Nova suit leur lumière douce.", "Im Kürbishain werfen kleine Laternen große Schatten. Nova folgt ihrem warmen Licht.", "En el Bosque calabaza, pequeños faroles dibujan grandes sombras. Nova sigue su luz cálida.", "No Bosque abóbora, pequenas lanternas criam grandes sombras. Nova segue a sua luz quente.", "Nel Bosco zucca, piccole lanterne proiettano grandi ombre. Nova segue la loro luce calda.");
        add("prism_objective_8", "Walk Pumpkin Grove and collect its ten Guardian fragments.", "Parcours le Bois citrouille et récupère les dix fragments de ses gardiens.", "Erkunde den Kürbishain und sammle die zehn Wächterfragmente.", "Recorre el Bosque calabaza y recoge sus diez fragmentos de guardianes.", "Percorre o Bosque abóbora e recolhe os dez fragmentos dos seus guardiões.", "Percorri il Bosco zucca e raccogli i dieci frammenti dei suoi guardiani.");
        add("prism_after_8", "The lantern facet glows without a flicker. The grove feels small and welcoming again.", "La facette des lanternes brille sans trembler. Le bois retrouve une douceur familière.", "Die Laternenfacette leuchtet ruhig. Der Hain wirkt wieder klein und einladend.", "La faceta de los faroles brilla sin temblar. El bosque vuelve a ser acogedor.", "A faceta das lanternas brilha sem tremer. O bosque volta a ser acolhedor.", "La faccia delle lanterne brilla senza tremare. Il bosco torna accogliente.");
        add("prism_title_9", "Ribbons of rose light", "Des rubans de lumière rose", "Bänder aus rosa Licht", "Cintas de luz rosa", "Fitas de luz rosa", "Nastri di luce rosa");
        add("prism_intro_9", "Rose Aurora unfurls ribbons across the sky. Nova follows their crossings, one quiet turn at a time.", "L’Aurore rose déroule des rubans dans le ciel. Nova suit leurs croisements, un détour à la fois.", "Die Rosenaurora breitet Bänder am Himmel aus. Nova folgt ihren Kreuzungen, eine ruhige Biegung nach der anderen.", "La Aurora rosa despliega cintas en el cielo. Nova sigue sus cruces, un giro tranquilo cada vez.", "A Aurora rosa estende fitas pelo céu. Nova segue os seus cruzamentos, uma curva de cada vez.", "L’Aurora rosa stende nastri nel cielo. Nova segue i loro incroci, una curva tranquilla alla volta.");
        add("prism_objective_9", "Follow Rose Aurora and collect its ten Guardian fragments.", "Suis l’Aurore rose et récupère les dix fragments de ses gardiens.", "Folge der Rosenaurora und sammle die zehn Wächterfragmente.", "Sigue la Aurora rosa y recoge sus diez fragmentos de guardianes.", "Segue a Aurora rosa e recolhe os dez fragmentos dos seus guardiões.", "Segui l’Aurora rosa e raccogli i dieci frammenti dei suoi guardiani.");
        add("prism_after_9", "The ribbons rest together in the Prism. Their colours remain distinct, even where they meet.", "Les rubans se rejoignent dans le Prisme. Leurs couleurs restent distinctes, même là où elles se croisent.", "Die Bänder ruhen zusammen im Prisma. Ihre Farben bleiben auch an den Kreuzungen erkennbar.", "Las cintas se unen en el Prisma. Sus colores siguen siendo distintos, incluso donde se cruzan.", "As fitas juntam-se no Prisma. As cores continuam distintas, mesmo onde se cruzam.", "I nastri si uniscono nel Prisma. I loro colori restano distinti, anche dove si incontrano.");
        add("prism_title_10", "The summit’s open window", "La fenêtre ouverte du sommet", "Das offene Fenster am Gipfel", "La ventana abierta de la cima", "A janela aberta do cume", "La finestra aperta della cima");
        add("prism_intro_10", "At Dream Summit, Nova finds a window facing every path below. There is room for one more reflection.", "Au Sommet des rêves, Nova trouve une fenêtre sur les chemins parcourus. Il reste une place pour un reflet.", "Am Traumgipfel findet Nova ein Fenster zu allen Wegen darunter. Ein Spiegelbild hat noch Platz.", "En la Cima de sueños, Nova encuentra una ventana a los caminos de abajo. Queda sitio para otro reflejo.", "No Cume dos sonhos, Nova encontra uma janela para os caminhos lá em baixo. Há lugar para mais um reflexo.", "Sulla Cima dei sogni, Nova trova una finestra sui sentieri sottostanti. C’è posto per un altro riflesso.");
        add("prism_objective_10", "Reach Dream Summit and collect its ten Guardian fragments.", "Explore le Sommet des rêves et récupère les dix fragments de ses gardiens.", "Erreiche den Traumgipfel und sammle die zehn Wächterfragmente.", "Alcanza la Cima de sueños y recoge sus diez fragmentos de guardianes.", "Chega ao Cume dos sonhos e recolhe os dez fragmentos dos seus guardiões.", "Raggiungi la Cima dei sogni e raccogli i dieci frammenti dei suoi guardiani.");
        add("prism_after_10", "The summit facet catches the view. Nova leaves the window open: every path can be visited again.", "La facette du sommet recueille le paysage. Nova laisse la fenêtre ouverte : chaque chemin peut être revisité.", "Die Gipfelfacette fängt die Aussicht ein. Nova lässt das Fenster offen: Jeder Weg kann erneut besucht werden.", "La faceta de la cima guarda el paisaje. Nova deja la ventana abierta: se puede volver a cada camino.", "A faceta do cume guarda a paisagem. Nova deixa a janela aberta: cada caminho pode ser visitado de novo.", "La faccia della cima custodisce il paesaggio. Nova lascia aperta la finestra: ogni sentiero si può visitare di nuovo.");
    }
    private PrismStoryStrings() { }
    private static void add(String key, String... values) {
        if (values.length != 6 || TEXT.put(key, values) != null) throw new IllegalArgumentException(key);
        for (String value : values) if (value == null || value.isEmpty()) throw new IllegalArgumentException(key);
    }
    public static String get(String language, String key, Object... args) {
        String[] row = TEXT.get(key);
        if (row == null) throw new IllegalArgumentException(key);
        String normalized = Strings.normalize(language);
        int index = Arrays.asList("en", "fr", "de", "es", "pt", "it").indexOf(normalized);
        return String.format(Locale.forLanguageTag(normalized), row[Math.max(0, index)], args);
    }
    public static Set<String> keys() { return Collections.unmodifiableSet(TEXT.keySet()); }
}
